S = "Hakeem Force Academy"
QS = [
(S, "What is the conjugate of the complex number 6+3i?", ["6+3i", "-6+3i", "6-3i", "-6-3i"], 2, "The conjugate of a+bi is a-bi, so only the sign of the imaginary part changes. Hence the conjugate of 6+3i is 6-3i.", "The product of a complex number and its conjugate is always a real number, a squared plus b squared.", [3302]),
(S, "What is the conjugate of the complex number 7+6i?", ["7-6i", "-7+6i", "7+6i", "-7-6i"], 0, "The conjugate of a+bi is a-bi, so the sign of the imaginary part is reversed. Hence the conjugate of 7+6i is 7-6i.", "Complex roots of a real-coefficient polynomial always occur in conjugate pairs.", [3303]),
(S, "What is the conjugate of a complex number a+bi?", ["a+bi", "-a+bi", "b+ai", "a-bi"], 3, "The conjugate of a complex number is found by changing the sign of its imaginary part. So the conjugate of a+bi is a-bi.", "Geometrically, the conjugate is the mirror image of the number in the real axis.", [3304]),
(S, "What is a composite number?", ["A number with exactly two factors", "A positive integer greater than 1 with more than two factors", "A number that is not divisible by 2", "A number with only one factor"], 1, "A composite number has at least one factor other than 1 and itself, so it has more than two factors. Examples are 4, 6, 8 and 9.", "The number 1 is neither prime nor composite.", [864]),
(S, "Which of these numbers is a composite number: 1, 5, 8, 13?", ["1", "5", "13", "8"], 3, "5 and 13 are prime and 1 is neither prime nor composite. 8 has factors 1, 2, 4 and 8, so it is composite.", "The smallest composite number is 4.", [4546]),
(S, "In the x,y coordinate system, what is the y-coordinate also called?", ["Abscissa", "Ordinate", "Origin", "Quadrant"], 1, "In a point (x, y), the x-value is called the abscissa and the y-value is called the ordinate.", "The point where both coordinates are zero is called the origin.", [2141, 2142, 2540, 220, 3834]),
(S, "Which of the following is the synonym of 'contain'?", ["Hold", "Release", "Avoid", "Spread"], 0, "To contain something means to have it inside or to hold it. 'Hold' is the closest in meaning.", "'Contain' can also mean to keep something under control, as in contain a fire.", [930, 3728]),
(S, "What is the meaning of 'contentment'?", ["Anger", "Satisfaction and happiness with what one has", "Greed", "Sadness"], 1, "Contentment is a state of being happy and satisfied with what one has.", "The related adjective is content, and its opposite is discontent.", [3250, 3501]),
(S, "What is the antonym of 'contentment'?", ["Satisfaction", "Peace", "Discontent", "Happiness"], 2, "Contentment means satisfaction, so its opposite is discontent, meaning dissatisfaction or unhappiness.", "Discontent can be used as both a noun and an adjective.", [3137]),
(S, "What is the antonym of 'controversy'?", ["Dispute", "Argument", "Debate", "Agreement"], 3, "Controversy means a prolonged public disagreement. Its opposite is agreement or harmony.", "The word controversial describes something that causes disagreement.", [3128]),
(S, "Choose the correct preposition: He should establish confidence ___ his clients.", ["in", "on", "upon", "above"], 0, "The correct collocation is 'confidence in' someone. So the sentence reads: He should establish confidence in his clients.", "We also say faith in, trust in and belief in.", [1656]),
(S, "Who conquered Sindh in 711-712 AD?", ["Tariq bin Ziyad", "Mahmud of Ghazni", "Muhammad bin Qasim", "Qutbuddin Aibak"], 2, "The young Arab general Muhammad bin Qasim conquered Sindh during the Umayyad caliphate. He defeated Raja Dahir.", "Sindh is therefore called Bab-ul-Islam, the gateway of Islam, in the subcontinent.", [231]),
(S, "In which year AD is the conquest of Sindh by Muhammad bin Qasim completed, as commonly given in Pakistani textbooks?", ["712", "632", "1001", "1192"], 0, "Muhammad bin Qasim landed in 711 AD and defeated Raja Dahir in 712 AD, completing the conquest of Sindh.", "Some sources give 711 AD for the invasion and 712 AD for the conquest.", [2383]),
(S, "Who conquered the fort of Khyber (Khaybar) in 7 AH?", ["Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Khalid bin Waleed (RA)", "Hazrat Abu Bakr (RA)"], 1, "The Muslims besieged the Jewish forts of Khyber, and Hazrat Ali (RA) led the final conquest of the main fort, Qamus. He was given the Prophet's flag.", "Hazrat Ali (RA) is known by the title Asadullah and Haidar-e-Karrar.", [4800]),
(S, "In which year AD was Khyber conquered by the Muslims?", ["622", "624", "628", "630"], 2, "The Battle of Khyber took place in Muharram 7 AH, which corresponds to about 628 AD.", "The conquest of Makkah took place later, in 8 AH.", [2546, 3340]),
(S, "Sahih Muslim is regarded as the most authentic book of hadith after which book?", ["Sunan Abu Dawud", "Jami at-Tirmidhi", "Sahih Bukhari", "Muwatta Imam Malik"], 2, "Scholars rank Sahih Bukhari first and Sahih Muslim second in authenticity among the hadith collections.", "Sahih Bukhari and Sahih Muslim together are called the Sahihain.", [2658]),
(S, "What is the term of office of the UN Secretary-General?", ["Three years", "Four years", "Five years", "Seven years"], 2, "The UN Secretary-General is appointed by the General Assembly on the recommendation of the Security Council for a term of five years, which can be renewed.", "Antonio Guterres has served since 2017 and his second term ends on 31 December 2026.", [1430]),
(S, "Which Islamic summit conference was held in Lahore, Pakistan in 1974?", ["First OIC Summit", "Second OIC Islamic Summit", "Third OIC Islamic Summit", "Fourth OIC Islamic Summit"], 1, "The Second Islamic Summit Conference of the OIC was hosted by Pakistan in Lahore in February 1974. It was chaired by Zulfikar Ali Bhutto.", "The first OIC summit was held in Rabat, Morocco, in 1969.", [4550]),
(S, "In which Pakistani city have SAARC summits been held?", ["Lahore", "Karachi", "Peshawar", "Islamabad"], 3, "Pakistan hosted the 4th SAARC Summit in Islamabad in 1988 and the 12th in Islamabad in 2004.", "The SAARC Secretariat is in Kathmandu, Nepal.", [4668]),
(S, "With which Afghan province does the Khyber Pass connect Pakistan?", ["Kandahar", "Herat", "Kabul", "Nangarhar"], 3, "The Khyber Pass leads from Pakistan through Torkham into Nangarhar Province of Afghanistan. The provincial capital is Jalalabad.", "The Khyber Pass lies in Khyber Pakhtunkhwa near Peshawar.", [5269]),
(S, "Into which sea does the Indus River flow?", ["Arabian Sea", "Red Sea", "Caspian Sea", "Bay of Bengal"], 0, "The Indus River flows through Pakistan and falls into the Arabian Sea near Karachi in Sindh.", "The Indus delta is near Thatta.", [5271]),
(S, "Which body regulates the oil and gas industry in Pakistan?", ["WAPDA", "NEPRA", "PTA", "OGRA"], 3, "The Oil and Gas Regulatory Authority (OGRA) regulates the midstream and downstream oil and gas sector of Pakistan.", "NEPRA regulates the electric power sector.", [4273]),
(S, "In which year did the construction of Mangla Dam start, as given by WAPDA?", ["1958", "1962", "1967", "1971"], 1, "WAPDA gives 1962 as the start of construction of Mangla Dam on the Jhelum, and it was completed in 1967.", "Some sources, including Wikipedia, give 1961 as the start year, so sources differ.", [2348]),
]
